package dev.soundsoftware.core.model

import kotlinx.serialization.Serializable

/** Persistent product record. Audio lives beside it as a canonical 16 kHz mono WAV. */
@OptIn(kotlinx.serialization.ExperimentalSerializationApi::class)
@Serializable
data class Recording(
    val id: String,
    val createdAt: Long,
    val durationMs: Long,
    val source: RecordingSource = RecordingSource.IMPORT,
    val deviceFileId: Long? = null,
    /** Title set by the user or generated by the summary step; null means "<date> 的录音". */
    val title: String? = null,
    val titleEditedByUser: Boolean = false,
    val audioBytes: Long = 0,
    val waveform: List<Float> = emptyList(),
    val stage: ProcessingStage = ProcessingStage.NEW,
    val progress: Float? = null,
    val stageText: String? = null,
    val error: String? = null,
    val options: TranscribeOptions? = null,
    val transcript: Transcript? = null,
    val speakers: List<Speaker> = emptyList(),
    val summary: MeetingSummary? = null,
    val qa: List<QaTurn> = emptyList(),
    val speakerAnalysis: SpeakerAnalysis? = null,
    /** null: legacy/not yet read or unsupported firmware; empty: verified, no hardware highlights. */
    @kotlinx.serialization.EncodeDefault(kotlinx.serialization.EncodeDefault.Mode.NEVER)
    val hardwareHighlights: List<RecordingHighlight>? = null,
)

@Serializable data class RecordingHighlight(val id: String, val positionMs: Long)

@Serializable enum class RecordingSource { DEVICE, IMPORT }

@Serializable enum class ProcessingStage { NEW, QUEUED, DIARIZING, TRANSCRIBING, SUMMARIZING, DONE, FAILED }

@Serializable enum class SceneTemplate(val title: String, val subtitle: String, val keyPointsTitle: String = "要点") {
    AUTO("自动判断", "根据逐字稿选择纪要类型"),
    MEETING("会议纪要", "决策 · 待办 · 章节"),
    INTERVIEW("访谈", "问答对 · 观点摘录", "问答与观点"),
    JOB_INTERVIEW("面试", "关键问答 · 经历与待核实项", "面试问答与经历"),
    LECTURE("课堂笔记", "知识点 · 复习提纲", "知识点"),
    TRANSCRIPT_ONLY("仅逐字稿", "不生成纪要"),
}

@Serializable
data class TranscribeOptions(
    val template: SceneTemplate = SceneTemplate.MEETING,
    val profileId: String = "qwen-cpu",
    /** null = automatic language detection. */
    val language: String? = "zh",
    val mixedChineseEnglish: Boolean = true,
    val speakerCount: Int? = null,
    val hotwords: List<String> = emptyList(),
) {
    init { require(speakerCount == null || speakerCount in 1..12) }
    /** Language hint actually given to the recognizer; mixed mode lets the model detect per window. */
    val effectiveLanguage: String? get() = if (mixedChineseEnglish) null else language
}

@Serializable
data class Transcript(
    val segments: List<Segment>,
    val model: String,
    val backend: String,
    val timestampQuality: String,
    val createdAt: Long,
    val warnings: List<String> = emptyList(),
)

@Serializable
data class Segment(
    val id: String,
    val text: String,
    val startMs: Long? = null,
    val endMs: Long? = null,
    val speakerId: String? = null,
    val edited: Boolean = false,
)

@Serializable
data class Speaker(val id: String, val index: Int, val name: String? = null) {
    val displayName: String get() = name ?: "说话人 $index"
}

@Serializable
data class MeetingSummary(
    val title: String? = null,
    val abstract: String = "",
    val todos: List<TodoItem> = emptyList(),
    val chapters: List<Chapter> = emptyList(),
    val keyPoints: List<String> = emptyList(),
    val template: SceneTemplate = SceneTemplate.MEETING,
    val model: String = "",
    val createdAt: Long = 0,
    val decisions: List<String> = emptyList(),
    val risks: List<String> = emptyList(),
    val openQuestions: List<String> = emptyList(),
    /** Keys are abstract, keyPoints/0, decisions/0, risks/0, openQuestions/0. */
    val evidence: Map<String, List<EvidenceRef>> = emptyMap(),
    val promptVersion: String = "",
    val sourceTranscriptHash: String = "",
)

@Serializable
data class EvidenceRef(val segmentId: String, val quote: String)

@Serializable
data class TodoItem(val id: String, val text: String, val owner: String? = null, val due: String? = null, val done: Boolean = false,
    val evidence: List<EvidenceRef> = emptyList())

@Serializable
data class Chapter(val startMs: Long, val title: String, val evidence: List<EvidenceRef> = emptyList())

@Serializable
data class QaTurn(val question: String, val answer: String, val createdAt: Long,
    val evidence: List<EvidenceRef> = emptyList(), val sourceTranscriptHash: String = "")

fun Recording.speakerName(id: String?): String? = speakers.firstOrNull { it.id == id }?.displayName

/** Removing a task edits this recording's notes; its audio, transcript and other tasks stay intact. */
fun Recording.withoutTodo(todoId: String): Recording = copy(summary=summary?.let { notes ->
    notes.copy(todos=notes.todos.filterNot {it.id==todoId})
})

@Serializable data class SpeakerAnalysis(val revision: String, val computedAt: Long, val requestedCount: Int?, val resultCount: Int)
